import { mkdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { files } from "./fixtures";

const outDir = fileURLToPath(new URL("../../test/fixtures/contract/", import.meta.url));
mkdirSync(outDir, { recursive: true });

const header: string[] = [
  "// generated by dashboard/scripts/gen-fixtures.ts, do not edit",
  "#pragma once",
  "",
  "#include <stddef.h>",
  "#include <stdint.h>",
  "",
];

for (const [name, bytes] of Object.entries(files)) {
  writeFileSync(`${outDir}${name}`, bytes);
  const ident = `FIXTURE_${name.replace(/\.[a-z]+$/, "").replace(/-/g, "_").toUpperCase()}`;
  const body = Array.from(bytes, (byte) => `0x${byte.toString(16).padStart(2, "0")}`);
  const rows: string[] = [];
  for (let index = 0; index < body.length; index += 12) rows.push(`    ${body.slice(index, index + 12).join(", ")},`);
  header.push(`static const uint8_t ${ident}[] = {`, ...rows, "};", `static const size_t ${ident}_LEN = sizeof(${ident});`, "");
}

writeFileSync(`${outDir}contract_fixtures.h`, header.join("\n"));
console.log(`wrote ${Object.keys(files).length} fixtures to ${outDir}`);
